import 'package:flutter/material.dart';\nimport 'package:provider/provider.dart';\nimport 'package:flutter_colorpicker/flutter_colorpicker.dart';\nimport '../providers/device_state_provider.dart';\nimport '../services/music_sync_engine.dart';\n\nclass ControlDashboard extends StatefulWidget {\n  final String deviceId;\n  const ControlDashboard({Key? key, required this.deviceId}) : super(key: key);\n\n  @override\n  State<ControlDashboard> createState() => _ControlDashboardState();\n}\n\nclass _ControlDashboardState extends State<ControlDashboard> {\n  late MusicSyncEngine _musicEngine;\n\n  @override\n  void initState() {\n    super.initState();\n    final provider = context.read<DeviceStateProvider>();\n    provider.connectSocket(widget.deviceId);\n    _musicEngine = MusicSyncEngine(provider, widget.deviceId);\n  }\n\n  @override\n  void dispose() {\n    _musicEngine.stopSync();\n    super.dispose();\n  }\n\n  @override\n  Widget build(BuildContext context) {\n    final state = context.watch<DeviceStateProvider>();\n\n    return Scaffold(\n      backgroundColor: const Color(0xFF1E1E1E),\n      appBar: AppBar(\n        title: const Text('Smart Bulb'),\n        backgroundColor: Colors.transparent,\n        elevation: 0,\n      ),\n      body: SafeArea(\n        child: Padding(\n          padding: const EdgeInsets.all(24.0),\n          child: Column(\n            children: [\n              // Power Toggle\n              Row(\n                mainAxisAlignment: MainAxisAlignment.spaceBetween,\n                children: [\n                  const Text('Power', style: TextStyle(color: Colors.white, fontSize: 24)),\n                  Switch(\n                    value: state.isOn,\n                    onChanged: (val) => state.setPower(val),\n                    activeColor: Colors.amber,\n                  ),\n                ],\n              ),\n              const SizedBox(height: 30),\n              \n              // Matter Color Picker\n              ColorPicker(\n                pickerColor: Color.fromRGBO(state.color[0], state.color[1], state.color[2], 1.0),\n                onColorChanged: (Color color) {\n                  state.updateColor(color.red, color.green, color.blue);\n                },\n                enableAlpha: false,\n                pickerAreaHeightPercent: 0.7,\n              ),\n              const SizedBox(height: 30),\n\n              // Music Sync Button\n              ElevatedButton.icon(\n                icon: Icon(_musicEngine.isSyncing ? Icons.stop : Icons.music_note),\n                label: Text(_musicEngine.isSyncing ? 'Stop Music Sync' : 'Start Music Sync'),\n                style: ElevatedButton.styleFrom(\n                  backgroundColor: _musicEngine.isSyncing ? Colors.red : Colors.deepPurple,\n                  padding: const EdgeInsets.symmetric(horizontal: 40, vertical: 15),\n                  shape: RoundedRectangleBorder(borderRadius: BorderRadius.circular(30)),\n                ),\n                onPressed: () async {\n                  if (_musicEngine.isSyncing) {\n                    _musicEngine.stopSync();\n                  } else {\n                    await _musicEngine.startSync();\n                  }\n                  setState(() {}); // refresh button UI\n                },\n              )\n            ],\n          ),\n        ),\n      ),\n    );\n  }\n}\n
